--
-- Table structure for table `hubstaff_activities`
--

CREATE TABLE `hubstaff_activities` (
  `id` bigint UNSIGNED NOT NULL,
  `hubstaff_member_id` bigint UNSIGNED NOT NULL,
  `hubstaff_project_id` bigint UNSIGNED DEFAULT NULL,
  `hubstaff_task_id` bigint UNSIGNED DEFAULT NULL,
  `tracked_date` date NOT NULL,
  `tracked_seconds` int NOT NULL DEFAULT '0',
  `keyboard_activity` int NOT NULL DEFAULT '0',
  `mouse_activity` int NOT NULL DEFAULT '0',
  `overall_activity` int NOT NULL DEFAULT '0',
  `synced_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `hubstaff_members`
--

CREATE TABLE `hubstaff_members` (
  `id` bigint UNSIGNED NOT NULL,
  `hubstaff_user_id` bigint UNSIGNED NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` bigint UNSIGNED DEFAULT NULL,
  `todos` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `integration_logs`
--

CREATE TABLE `integration_logs` (
  `id` bigint UNSIGNED NOT NULL,
  `source` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tasks_synced` int NOT NULL DEFAULT '0',
  `message` text COLLATE utf8mb4_unicode_ci,
  `synced_at` timestamp NOT NULL,
