  PRIMARY KEY (`id`),
  KEY `ac_tasks_project_idx` (`project_id`),
  KEY `ac_tasks_assignee_idx` (`assignee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

